<?php
ob_start();require 'C:/xampp/htdocs/boticav1/config/database.php';require __DIR__.'/../integration/ali-product-knowledge.php';$db=appPdoConnection();ob_end_clean();$changes=[];foreach($db->query('SELECT product_id FROM Ali_ProductoFicha')->fetchAll(PDO::FETCH_COLUMN) as $id){$p=aliKnowledgeProduct($db,$id);$f=aliKnowledgeRead($db,$id);if(!$p||trim((string)$p['ProductoDesc'])!==''||!hash_equals($f['catalog_hash'],aliKnowledgeHash($p)))continue;$changes[]=['id'=>$id,'previous_description'=>$p['ProductoDesc'],'previous_hash'=>$f['catalog_hash'],'description'=>$f['characteristics']];}
if(!$changes){echo "No empty catalog descriptions require synchronization.\n";exit;}$backup=__DIR__.'/../output/catalog-spec-sync-'.date('Ymd-His').'.json';if(file_put_contents($backup,json_encode($changes,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT))===false)throw new RuntimeException('Backup failed');$db->beginTransaction();try{$count=0;foreach($changes as $c){$p=aliKnowledgeProduct($db,$c['id'],true);if(trim((string)$p['ProductoDesc'])!==''||!hash_equals($c['previous_hash'],aliKnowledgeHash($p)))continue;$s=$db->prepare('UPDATE Gen_Producto SET ProductoDesc=? WHERE IdProducto=?');$s->execute([$c['description'],$c['id']]);$p['ProductoDesc']=$c['description'];$s=$db->prepare('UPDATE Ali_ProductoFicha SET catalog_hash=? WHERE product_id=?');$s->execute([aliKnowledgeHash($p),$c['id']]);$count++;}$db->commit();echo "Synchronized reviewed characteristics into $count empty catalog descriptions. Backup retained. Prices, stock, usage references and quote records unchanged.\n";}catch(Throwable $e){$db->rollBack();throw $e;}
